///////// 1. 변수 및 선언 영역 /////////
scwin.nPreRow = -1;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        // cfi콤보셋팅
        ins_cfi_set(dts_cfi_group, "ULDINS16100.xml", SCREN_PROCS_TP_CD_01, "07", "D", "", "", "G");
        // hidden패널
        panel_12.hide();
        scwin.init();
        const arrObjectApct = [txb_APCT_NM, txb_APCT_FAX_NO, txb_APCT_TEL_NO, txb_APCT_INNR_NO];
        for (let i = 0; i < arrObjectApct.length; i++) {
            fn_apct_delchar(arrObjectApct[i]);
        }
        txb_SRCH_STD_CD.focus();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS16100.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    $c.cm.PanelToGroupBox(panel_1);
    $c.cm.PanelToGroupBox(panel_2);
    // PanelToGroupBox(panel_4);
    // PanelToGroupBox(panel_5);

    // 콤보 세팅.
    scwin.setCombo();

    // 기본값 세팅
    scwin.setDefaultVal();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_ApplInfo_OnLoadError
 * @description dts_ApplInfo 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_ApplInfo_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_ApplInfo);

        // 조회버튼 활성.
        fn_SetDisableSelectBtn(btn_search, false);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS16100.dts_ApplInfo_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_ApplInfo_OnLoadCompleted
 * @description dts_ApplInfo 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_ApplInfo_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_ApplInfo.errorMsg) {
            await $c.win.alert(dts_ApplInfo.errorMsg);
        } else {
            txb_TotalCnt.setValue("총 " + rowcount + "건");
        }

        // 조회버튼 활성.
        fn_SetDisableSelectBtn(btn_search, false);

        // 데이터가 없는 경우
        if (rowcount === 0) {
            fn_CtrlBtn_temp("no_data");
        } else {
            fn_CtrlBtn_temp("update");
            let CFI_CD = dts_ApplInfo.getCellData(dts_ApplInfo.getRowPosition(), "CFI_CD");
            scwin.setChange(CFI_CD);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS16100.dts_ApplInfo_OnLoadCompleted" });
    }
};

