/**
 * @method
 * @name dts_ApplInfo_OnRowPosChanged
 * @description Appl Info On Row Pos Changed 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_ApplInfo_OnRowPosChanged = function(row) {
    try {
        dts_ApplInfo.undoRow(scwin.nPreRow);
        scwin.nPreRow = row;
        let CFI_CD = dts_ApplInfo.getCellData(dts_ApplInfo.getRowPosition(), "CFI_CD");
        if (CFI_CD !== undefined) {
            scwin.setChange(CFI_CD);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS16100.dts_ApplInfo_OnRowPosChanged" });
    }
};

