 * @description cmb_cb_p_group onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_cb_p_group_onselchange = function() {
    try {
        if (cmb_cb_p_group.getValue() !== "") {
            ins_cfi_set(dts_cfi_attr1, "ULDINS16100.xml", SCREN_PROCS_TP_CD_01, "07", "D", cmb_cb_p_group.getValue(), "1", "");
            ins_cfi_set(dts_cfi_attr2, "ULDINS16100.xml", SCREN_PROCS_TP_CD_01, "07", "D", cmb_cb_p_group.getValue(), "2", "");
            ins_cfi_set(dts_cfi_attr3, "ULDINS16100.xml", SCREN_PROCS_TP_CD_01, "07", "D", cmb_cb_p_group.getValue(), "3", "");
            ins_cfi_set(dts_cfi_attr4, "ULDINS16100.xml", SCREN_PROCS_TP_CD_01, "07", "D", cmb_cb_p_group.getValue(), "4", "");
            // alert(dts_cfi_attr1.NameValue(2,"HEAD_NM"));
            label_attr1.setValue("(" + dts_cfi_attr1.getCellData(2, "HEAD_NM") + ")");
            label_attr2.setValue("(" + dts_cfi_attr2.getCellData(2, "HEAD_NM") + ")");
            label_attr3.setValue("(" + dts_cfi_attr3.getCellData(2, "HEAD_NM") + ")");
            label_attr4.setValue("(" + dts_cfi_attr4.getCellData(2, "HEAD_NM") + ")");
        }
        scwin.changeCfi();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS16100.cmb_cb_p_group_onselchange" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name ins_Search
 * @description ins Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_Search = async function() {
    // 데이터셋 초기화
    scwin.initDs();

    // 조회조건 체크.
    if (!await scwin.chkValid("select")) {
        return;
    }

    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20220922
    fn_SetDisableSelectBtn(btn_search, true);

    // Lodaing~~~ 표시
