/**
 * @method
 * @name ins_Delete
 * @description 표준코드 삭제 사전작업
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_Delete = async function() {
    // 사전체크
    if (!await scwin.chkValid("delete")) {
        // 삭제요청건이 있는 경우 ULDINS11000 화면에서 삭제함.
        fn_alertRequiredDelByWeb();
        return;
    }

    // 사전체크
    if (!fn_alertDelConfirm()) {
        return;
    }

    // 삭제사유 세팅 팝업
    ins_popupOpen(txb_DEL_RSN, "", "ULDINS91500", "삭제사유", "470", "170");
};

/**
 * @method
 * @name chkValid
 * @description 사전체크
 * @param {*} pGubun pGubun
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkValid = async function(pGubun) {
    if (pGubun === undefined) {
        return true;
    }
    if (pGubun === "select") {
        if ($c.stf.compareFromToDate2(edt_FROM_ISU_DD, edt_TO_ISU_DD) === false) {
            return false;
        }
        if ($c.stf.compareFromToDate2(edt_FROM_STD_CD_GRNT_DD, edt_TO_STD_CD_GRNT_DD) === false) {
            return false;
        }
    } else if (pGubun === "save") {
        if (!$c.cp.isModified(dts_ApplInfo)) {
            await $c.win.alert("변경된 데이터가 없습니다.");
            return false;
        }
        if (txb_ISU_NM.getValue() === "" || txb_ISU_NM.getValue().indexOf(" ") === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "한글종목명"));
            txb_ISU_NM.focus();
            return false;
        }
        if (txb_ISU_ABBRV.getValue() === "" || txb_ISU_ABBRV.getValue().indexOf(" ") === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "한글종목약명"));
            txb_ISU_ABBRV.focus();
            return false;
        }
        if (txb_ISU_ENG_NM.getValue() === "" || txb_ISU_ENG_NM.getValue().indexOf(" ") === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "영문종목명"));
            txb_ISU_ENG_NM.focus();
            return false;
        }
        if (txb_ISU_ENG_ABBRV.getValue() === "" || txb_ISU_ENG_ABBRV.getValue().indexOf(" ") === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "영문종목약명"));
            txb_ISU_ENG_ABBRV.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_ISU_NM, 80, "한글종목명")) {
            txb_ISU_NM.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_ISU_ABBRV, 40, "한글종목약명")) {
            txb_ISU_ABBRV.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_ISU_ENG_NM, 80, "영문종목명")) {
            txb_ISU_ENG_NM.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_ISU_ENG_ABBRV, 40, "영문종목약명")) {
            txb_ISU_ENG_ABBRV.focus();
            return false;
        }
        if (txb_ISUR_CD.getValue() === "") {
            await $c.win.alert("발행기관 코드를 확인하세요.");
            txb_ISUR_CD.focus();
            return false;
        }
        if (txb_ISU_NM.getValue() === "") {
            await $c.win.alert("기준명을 확인하세요.");
            txb_ISU_NM.focus();
            return false;
        }
        if (txb_UNQ_ISU_NM.getValue() === "") {
            await $c.win.alert("고유명을 확인하세요.");
            txb_UNQ_ISU_NM.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_UNQ_ISU_NM, 20, "한글고유명")) {
            // txb_UNQ_ISU_NM.value = "";
            txb_UNQ_ISU_NM.focus();
            return false;
        }
        if (txb_UNQ_ISU_ENG_NM.getValue() === "") {
            await $c.win.alert("고유명(영문)을 확인하세요.");
            txb_UNQ_ISU_ENG_NM.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_UNQ_ISU_ENG_NM, 20, "영문고유명")) {
            // txb_UNQ_ISU_ENG_NM.value = "";
            txb_UNQ_ISU_ENG_NM.focus();
            return false;
        }
        if (edt_ISU_DD.getValue() === "") {
            await $c.win.alert("발행일을 확인하세요.");
            edt_ISU_DD.focus();
            return false;
        }
        if (edt_EXP_DD.getValue() === "") {
            await $c.win.alert("상환일(만기일)을 확인하세요.");
            edt_EXP_DD.focus();
            return false;
        }
        if (fn_CheckDateObj(edt_ISU_DD, "발행일")) return false;
        if (fn_CheckDateObj(edt_EXP_DD, "상환일(만기일)")) return false;
        if (edt_YY1_BAS_YD.getValue() === "") {
            await $c.win.alert("연수익률을 확인하세요.");
            edt_YY1_BAS_YD.focus();
            return false;
        }
        if (edt_DC_SALES.getValue() === "") {
            await $c.win.alert("할인매출액을 확인하세요.");
            edt_DC_SALES.focus();
            return false;
        }
        if (edt_DC_RT.getValue() === "") {
            await $c.win.alert("할인율을 확인하세요.");
            edt_DC_RT.focus();
            return false;
        }
        if (cmb_CURR_TP_CD.getValue() === "") {
            await $c.win.alert("발행통화를 확인하세요.");
            cmb_CURR_TP_CD.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_BRN_NM, 80, "지점명")) {
            txb_BRN_NM.focus();
            return false;
        }

        // CFI체크
        if (cmb_cb_p_group.getValue() === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_그룹"));
            cmb_cb_p_group.focus();
            return false;
        }
        if (cmb_cb_p_attr_1.getValue() === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_1차속성"));
            cmb_cb_p_attr_1.focus();
            return false;
        }
        if (cmb_cb_p_attr_2.getValue() === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_2차속성"));
            cmb_cb_p_attr_2.focus();
            return false;
        }
        if (cmb_cb_p_attr_3.getValue() === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_3차속성"));
            cmb_cb_p_attr_3.focus();
            return false;
        }
        if (cmb_cb_p_attr_4.getValue() === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_4차속성"));
            cmb_cb_p_attr_4.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txa_NUSUAL_ISU_COND_CONTN, 60, "특이발행조건")) {
            // txb_ISU_ENG_ABBRV.value = "";
            txa_NUSUAL_ISU_COND_CONTN.focus();
            return false;
        }
    } else if (pGubun === "delete") {
        // 삭제 요청건이 존재하는지 체크
        let nRow = dts_ApplInfo.getRowPosition();
        const nDelCnt = dts_ApplInfo.getCellData(nRow, "DEL_CNT");
        if (Number(nDelCnt) > 0) {
            // 삭제요청건 존재
            return false;
        }
    }
    return true;
};

